// Live data for the easyIDE site. Commits, contributors, releases and repo numbers come straight from
// the GitHub API in the visitor's browser, so they are current on every load. Lines of code (which the
// API cannot give) come from data/stats.json, regenerated by tools/site-stats.py on every deploy.
const REPO = "ravibh5522/easyIDE";
const API = "https://api.github.com/repos/" + REPO;
const CACHE_MS = 5 * 60 * 1000; // unauthenticated API: 60 requests/hour per visitor
const MAX_PAGES = 10;
const DAY = 86400000;
const fmt = new Intl.NumberFormat("en");
const compact = new Intl.NumberFormat("en", { notation: "compact" });

function cached(key) {
  try {
    const hit = JSON.parse(sessionStorage.getItem(key));
    return hit && Date.now() - hit.at < CACHE_MS ? hit.data : null;
  } catch { return null; }
}

function remember(key, data) {
  try { sessionStorage.setItem(key, JSON.stringify({ at: Date.now(), data })); } catch { /* storage off */ }
}

async function json(url) {
  const hit = cached(url);
  if (hit) return hit;
  const res = await fetch(url, { headers: { Accept: "application/vnd.github+json" } });
  if (!res.ok) throw new Error(res.status + " " + url);
  const data = await res.json();
  remember(url, data);
  return data;
}

/** Commits of the last 12 months, newest first: enough for the heatmap, the weekly chart and the leaderboard. */
async function commits() {
  const since = new Date(Date.now() - 365 * DAY).toISOString();
  const all = [];
  for (let page = 1; page <= MAX_PAGES; page++) {
    const batch = await json(`${API}/commits?per_page=100&page=${page}&since=${since}`);
    all.push(...batch);
    if (batch.length < 100) break;
  }
  return all;
}

// Same origin and changed by every deploy: never served from the session cache, so a visit right after
// a deploy cannot pair a new page with an old stats file.
const stats = () => fetch("data/stats.json", { cache: "no-cache" }).then((r) => (r.ok ? r.json() : null)).catch(() => null);

function el(tag, attrs = {}, text) {
  const node = document.createElementNS(tag === "svg" || attrs.svg ? "http://www.w3.org/2000/svg" : "http://www.w3.org/1999/xhtml", tag);
  for (const [k, v] of Object.entries(attrs)) if (k !== "svg") node.setAttribute(k, v);
  if (text != null) node.textContent = text;
  return node;
}
const svgEl = (tag, attrs, text) => el(tag, { ...attrs, svg: true }, text);

// One tooltip for the page, placed beside the pointer or the focused mark.
const tip = document.body.appendChild(el("div", { class: "tip", role: "status" }));
function hover(target, html, focusable = true) {
  const show = (x, y) => {
    tip.innerHTML = html;
    tip.style.opacity = 1;
    const w = tip.offsetWidth;
    tip.style.left = Math.min(x + 14, innerWidth - w - 8) + "px";
    tip.style.top = (y - tip.offsetHeight - 10) + "px";
  };
  target.addEventListener("mousemove", (e) => show(e.clientX, e.clientY));
  target.addEventListener("focus", () => { const r = target.getBoundingClientRect(); show(r.left + r.width / 2, r.top); });
  for (const ev of ["mouseleave", "blur"]) target.addEventListener(ev, () => { tip.style.opacity = 0; });
  if (focusable) target.setAttribute("tabindex", "0");
}

function tableView(host, head, rows) {
  const details = host.appendChild(el("details", { class: "table" }));
  details.appendChild(el("summary", {}, "Show as table"));
  const table = details.appendChild(el("table"));
  const tr = table.appendChild(el("tr"));
  head.forEach((h, i) => tr.appendChild(el("th", i ? { class: "num" } : {}, h)));
  rows.forEach((r) => {
    const row = table.appendChild(el("tr"));
    r.forEach((c, i) => row.appendChild(el("td", i ? { class: "num" } : {}, c)));
  });
}

/** Horizontal bars, one series: value at the tip, 4px rounded end, square at the baseline. */
function bars(host, rows, unit) {
  // Drawn at the container's real width, so text stays 12px on a phone instead of shrinking with a viewBox.
  const width = Math.max(host.clientWidth, 280), labelW = Math.min(170, width * 0.38), barH = 18, gap = 12, room = 56;
  const max = Math.max(...rows.map((r) => r.value), 1);
  const svg = svgEl("svg", { viewBox: `0 0 ${width} ${rows.length * (barH + gap)}`, role: "img" });
  rows.forEach((r, i) => {
    const y = i * (barH + gap);
    const w = Math.max(2, (r.value / max) * (width - labelW - room));
    svg.appendChild(svgEl("text", { x: labelW - 10, y: y + barH * 0.72, "text-anchor": "end" }, r.label));
    const hit = svg.appendChild(svgEl("rect", { class: "hit", x: labelW, y: y - gap / 2, width: width - labelW, height: barH + gap }));
    svg.appendChild(svgEl("path", { class: "mark", d: `M${labelW},${y}h${w - 4}a4,4 0 0 1 4,4v${barH - 8}a4,4 0 0 1 -4,4h${-(w - 4)}z` }));
    svg.appendChild(svgEl("text", { class: "value", x: labelW + w + 8, y: y + barH * 0.72 }, compact.format(r.value)));
    hover(hit, `<b>${r.label}</b>${fmt.format(r.value)} ${unit}`);
  });
  host.appendChild(el("div", { class: "chart" })).appendChild(svg);
  tableView(host, ["", unit], rows.map((r) => [r.label, fmt.format(r.value)]));
}

/** Columns over time, one series, with clean y ticks and the peak labelled. */
function columns(host, rows, unit) {
  const width = Math.max(host.clientWidth, 280), height = 220, left = 32, bottom = 24, top = 18;
  const max = Math.max(...rows.map((r) => r.value), 1);
  const step = Math.max(1, Math.ceil(max / 4 / 5) * 5);
  const ceil = Math.ceil(max / step) * step;
  const plotH = height - bottom - top, slot = (width - left) / rows.length;
  const colW = Math.min(24, slot - 2);
  const y = (v) => top + plotH - (v / ceil) * plotH;
  const svg = svgEl("svg", { viewBox: `0 0 ${width} ${height}`, role: "img" });
  const grid = svg.appendChild(svgEl("g", { class: "grid" }));
  for (let v = 0; v <= ceil; v += step) {
    grid.appendChild(svgEl("line", { x1: left, x2: width, y1: y(v), y2: y(v) }));
    svg.appendChild(svgEl("text", { x: left - 6, y: y(v) + 4, "text-anchor": "end" }, compact.format(v)));
  }
  const peak = rows.reduce((a, b) => (b.value > a.value ? b : a), rows[0]);
  const every = Math.ceil(rows.length / Math.max(2, Math.floor(width / 90)));
  rows.forEach((r, i) => {
    const x = left + i * slot + (slot - colW) / 2, h = (r.value / ceil) * plotH;
    const hit = svg.appendChild(svgEl("rect", { class: "hit", x: left + i * slot, y: top, width: slot, height: plotH }));
    if (h > 0) {
      const r4 = Math.min(4, h);
      svg.appendChild(svgEl("path", { class: "mark", d: `M${x},${y(0)}v${-(h - r4)}a${r4},${r4} 0 0 1 ${r4},${-r4}h${colW - 2 * r4}a${r4},${r4} 0 0 1 ${r4},${r4}v${h - r4}z` }));
    }
    if (r === peak && r.value > 0) svg.appendChild(svgEl("text", { class: "value", x: x + colW / 2, y: y(r.value) - 6, "text-anchor": "middle" }, r.value));
    if (i % every === 0) svg.appendChild(svgEl("text", { x: x + colW / 2, y: height - 6, "text-anchor": "middle" }, r.label));
    hover(hit, `<b>${r.title}</b>${fmt.format(r.value)} ${unit}`);
  });
  host.appendChild(el("div", { class: "chart" })).appendChild(svg);
  tableView(host, ["", unit], rows.map((r) => [r.title, fmt.format(r.value)]));
}

const dayKey = (d) => d.toISOString().slice(0, 10);
const startOfWeek = (d) => { const s = new Date(d); s.setUTCHours(0, 0, 0, 0); s.setUTCDate(s.getUTCDate() - s.getUTCDay()); return s; };
const shortDate = (d) => d.toLocaleDateString("en", { month: "short", day: "numeric", timeZone: "UTC" });

/** GitHub-style calendar: 53 weeks x 7 days, one hue from faint to full by commit count. */
function heatmap(host, list) {
  const perDay = {};
  list.forEach((c) => { const k = c.commit.author.date.slice(0, 10); perDay[k] = (perDay[k] || 0) + 1; });
  const max = Math.max(...Object.values(perDay), 1);
  const level = (n) => (n === 0 ? 0 : Math.ceil((n / max) * 4));
  const fills = ["rgba(255,255,255,.06)", "rgba(255,138,61,.3)", "rgba(255,138,61,.5)", "rgba(255,138,61,.75)", "#ff8a3d"];
  // Cells grow with the container (up to 18px) so the 12px labels never scale; a phone scrolls instead.
  const left = 28, top = 18, gap = 3;
  const cell = Math.max(10, Math.min(18, Math.floor((Math.max(host.clientWidth, 640) - left) / 53) - gap));
  const first = startOfWeek(new Date(Date.now() - 364 * DAY));
  const svg = svgEl("svg", { viewBox: `0 0 ${left + 53 * (cell + gap)} ${top + 7 * (cell + gap) + 22}`, role: "img" });
  ["Mon", "Wed", "Fri"].forEach((d, i) => svg.appendChild(svgEl("text", { x: 0, y: top + (1 + i * 2) * (cell + gap) + 9 }, d)));
  let lastMonth = -1;
  const today = dayKey(new Date());
  for (let w = 0; w < 53; w++) {
    for (let d = 0; d < 7; d++) {
      const day = new Date(first.getTime() + (w * 7 + d) * DAY), key = dayKey(day);
      if (key > today) continue;
      if (d === 0 && day.getUTCMonth() !== lastMonth && day.getUTCDate() <= 7) {
        lastMonth = day.getUTCMonth();
        svg.appendChild(svgEl("text", { x: left + w * (cell + gap), y: 11 }, day.toLocaleDateString("en", { month: "short", timeZone: "UTC" })));
      }
      const n = perDay[key] || 0;
      const rect = svg.appendChild(svgEl("rect", { x: left + w * (cell + gap), y: top + d * (cell + gap), width: cell, height: cell, rx: 2, fill: fills[level(n)] }));
      // Not focusable: 365 tab stops would bury the page. The summary line below carries the numbers.
      hover(rect, `<b>${n} commit${n === 1 ? "" : "s"}</b>${day.toLocaleDateString("en", { weekday: "short", month: "short", day: "numeric", year: "numeric", timeZone: "UTC" })}`, false);
    }
  }
  const legendY = top + 7 * (cell + gap) + 8; // the calendar scrolls sideways on a phone rather than shrinking
  const lx = left + 53 * (cell + gap) - 5 * (cell + gap) - 70;
  svg.appendChild(svgEl("text", { x: lx - 6, y: legendY + 9, "text-anchor": "end" }, "Less"));
  fills.forEach((f, i) => svg.appendChild(svgEl("rect", { x: lx + i * (cell + gap), y: legendY, width: cell, height: cell, rx: 2, fill: f })));
  svg.appendChild(svgEl("text", { x: lx + 5 * (cell + gap) + 4, y: legendY + 9 }, "More"));
  const box = host.appendChild(el("div", { class: "chart scroll" }));
  box.appendChild(svg);
  box.scrollLeft = box.scrollWidth; // open on the recent months when it has to scroll
  const busiest = Object.entries(perDay).sort((a, b) => b[1] - a[1])[0];
  const active = Object.keys(perDay).length;
  if (busiest) host.appendChild(el("p", { class: "muted" }, `${fmt.format(list.length)} commits on ${active} days in the last 12 months; busiest day ${busiest[0]} with ${busiest[1]}.`));
}

function weeklyRows(list) {
  if (!list.length) return [];
  const count = {};
  list.forEach((c) => { const k = dayKey(startOfWeek(new Date(c.commit.author.date))); count[k] = (count[k] || 0) + 1; });
  const rows = [];
  for (let w = startOfWeek(new Date(list[list.length - 1].commit.author.date)); w <= new Date(); w = new Date(w.getTime() + 7 * DAY)) {
    rows.push({ label: shortDate(w), title: "Week of " + shortDate(w), value: count[dayKey(w)] || 0 });
  }
  return rows;
}

/** Commit authors merged by the repo's .mailmap (data/stats.json carries it), most commits first. */
function leaderboard(list, aliases) {
  const people = {};
  list.forEach((c) => {
    const email = c.commit.author.email;
    const name = aliases[email] || c.commit.author.name;
    const p = (people[name] ||= { name, commits: 0, login: null, avatar: null });
    p.commits++;
    if (c.author && !p.login) { p.login = c.author.login; p.avatar = c.author.avatar_url; }
  });
  return Object.values(people).sort((a, b) => b.commits - a.commits);
}

function personCell(p) {
  const wrap = el("div", { class: "person" });
  wrap.appendChild(p.avatar ? el("img", { src: p.avatar + "&s=72", alt: "", loading: "lazy" }) : el("span", { class: "initial" }, p.name[0]));
  const who = wrap.appendChild(el("div"));
  who.appendChild(p.login ? el("a", { href: "https://github.com/" + p.login }, p.name) : el("b", {}, p.name));
  return wrap;
}

function contributorsTable(host, people, total) {
  const table = host.appendChild(el("table"));
  const head = table.appendChild(el("tr"));
  ["Contributor", "Commits", "Share"].forEach((h, i) => head.appendChild(el("th", i ? { class: "num" } : {}, h)));
  people.forEach((p) => {
    const tr = table.appendChild(el("tr"));
    tr.appendChild(el("td")).appendChild(personCell(p));
    tr.appendChild(el("td", { class: "num" }, fmt.format(p.commits)));
    tr.appendChild(el("td", { class: "num" }, Math.round((p.commits / total) * 100) + "%"));
  });
}

function recent(host, list, aliases) {
  const ul = host.appendChild(el("ul", { class: "list" }));
  list.slice(0, 8).forEach((c) => {
    const li = ul.appendChild(el("li"));
    const a = li.appendChild(el("a", { href: c.html_url }, c.commit.message.split("\n")[0].slice(0, 110)));
    a.style.color = "var(--fg)";
    li.appendChild(el("span", { class: "muted" }, ` - ${aliases[c.commit.author.email] || c.commit.author.name}, ${new Date(c.commit.author.date).toLocaleDateString("en", { month: "short", day: "numeric" })}`));
  });
}

const still = matchMedia("(prefers-reduced-motion: reduce)").matches;

/** Sets every [data-stat=name]. With [num], a headline number counts up from 0 when it scrolls into view. */
function setStat(name, value, num, format = (n) => fmt.format(n)) {
  document.querySelectorAll(`[data-stat="${name}"]`).forEach((n) => {
    if (num == null || still || !n.closest(".numbers")) { n.textContent = value; return; }
    n.textContent = format(0);
    whenVisible(n, () => {
      const start = performance.now(), ms = 1400;
      const tick = (t) => {
        const k = Math.min(1, (t - start) / ms), eased = 1 - Math.pow(1 - k, 3);
        n.textContent = k < 1 ? format(Math.round(num * eased)) : value;
        if (k < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    });
  });
}

function whenVisible(node, fn) {
  const io = new IntersectionObserver((entries) => {
    if (entries.some((e) => e.isIntersecting)) { io.disconnect(); fn(); }
  }, { threshold: 0.15 });
  io.observe(node);
}

// Sections fade up as they scroll in (the CSS only hides them once this script runs).
document.querySelectorAll(".reveal").forEach((n) => whenVisible(n, () => n.classList.add("in")));

/** The hero's terminal types a short session, then starts over. */
function typer(pre) {
  const script = [
    ["$ ", "sudo apt-get install -y python3 git"],
    ["", "Setting up python3 (3.12.3) ... done"],
    ["$ ", "pip install flask"],
    ["", "Successfully installed flask-3.1"],
    ["$ ", "npm install -g @anthropic-ai/claude-code"],
    ["", "added 1 package in 9s"],
    ["$ ", 'git commit -m "first commit from my tablet"'],
    ["", "[main 4f1c2ab] first commit from my tablet"],
  ];
  const span = (cls, text) => { const s = el("span", { class: cls }, text); pre.appendChild(s); pre.scrollTop = pre.scrollHeight; return s; };
  const cursor = el("span", { class: "cursor" });
  let line = 0;
  const next = () => {
    if (line === script.length) { setTimeout(() => { pre.textContent = ""; line = 0; next(); }, 2600); return; }
    const [prompt, text] = script[line++];
    if (!prompt) { span("o", text + "\n"); pre.appendChild(cursor); setTimeout(next, 500); return; }
    span("p", prompt);
    const cmd = span("", "");
    pre.appendChild(cursor);
    let i = 0;
    const type = () => {
      cmd.textContent = text.slice(0, ++i);
      pre.scrollTop = pre.scrollHeight;
      if (i < text.length) setTimeout(type, 28 + Math.random() * 40);
      else { cmd.textContent += "\n"; setTimeout(next, 420); }
    };
    setTimeout(type, 300);
  };
  if (still) { script.forEach(([p, t]) => span(p ? "p" : "o", p + t + "\n")); return; }
  next();
}

/** The hero tablet plays the real screen recordings in turn; the pills under it pick one. */
function clips(video) {
  const buttons = [...document.querySelectorAll("[data-clip]")];
  const show = (name) => {
    buttons.forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.clip === name)));
    video.poster = `media/hero-${name}.jpg`;
    video.src = `media/hero-${name}.mp4`;
    if (!still) video.play().catch(() => {});
  };
  buttons.forEach((b) => b.addEventListener("click", () => show(b.dataset.clip)));
  video.addEventListener("ended", () => {
    const at = buttons.findIndex((b) => b.getAttribute("aria-pressed") === "true");
    show(buttons[(at + 1) % buttons.length].dataset.clip);
  });
  if (still) video.removeAttribute("autoplay"), video.pause();
}

/** The homepage's contributor chips: lead developer first, then everyone else, then an open seat. */
function peopleRow(host, people) {
  people.slice(0, 8).forEach((p, i) => {
    const chip = host.appendChild(p.login ? el("a", { href: "https://github.com/" + p.login }) : el("div"));
    if (p.login === "ravibh5522") chip.classList.add("is-lead");
    chip.appendChild(p.avatar ? el("img", { src: p.avatar + "&s=88", alt: "", loading: "lazy" }) : el("span", { class: "initial" }, p.name[0]));
    const who = chip.appendChild(el("span"));
    who.appendChild(el("b", {}, p.name));
    who.appendChild(el("small", {}, (p.login === "ravibh5522" ? "Lead developer · " : "") + fmt.format(p.commits) + " commits"));
  });
  const you = host.appendChild(el("a", { class: "you", href: "https://github.com/ravibh5522/easyIDE#contributing" }));
  you.appendChild(el("span", { class: "initial" }, "+"));
  you.appendChild(el("span", {}, "You? Start contributing"));
}

function failed(host, error) {
  host.appendChild(el("p", { class: "muted" }, "Live data could not be loaded (" + error.message + "). See it on GitHub instead."));
}

async function run() {
  const need = (id) => document.getElementById(id);
  const [liveRepo, local, liveList, liveReleases] = await Promise.all([
    json(API).catch(() => null),
    stats(),
    commits().catch((e) => e),
    json(`${API}/releases?per_page=20`).catch(() => null),
  ]);
  // Live first; the deploy-time snapshot when GitHub refuses (its limit is per IP, often shared).
  const snap = local && local.snapshot;
  const stale = (liveList instanceof Error || !liveRepo || !liveReleases) && snap;
  const repo = liveRepo || (snap && snap.repo);
  const releases = liveReleases || (snap && snap.releases);
  const list = liveList instanceof Error && snap && snap.commits ? snap.commits : liveList;
  if (stale) {
    document.querySelectorAll(".chart-head span").forEach((n) => { n.textContent = `as of ${local.generated}`; });
  }
  if (repo) {
    setStat("stars", fmt.format(repo.stargazers_count), repo.stargazers_count);
    setStat("forks", fmt.format(repo.forks_count));
    setStat("issues", fmt.format(repo.open_issues_count));
  }
  if (local) {
    setStat("lines", compact.format(local.code.lines), local.code.lines, (n) => compact.format(n));
    setStat("tests", fmt.format(local.code.test_cases), local.code.test_cases);
    setStat("decisions", fmt.format(local.decisions), local.decisions);
    setStat("generated", local.generated);
    if (need("languages")) bars(need("languages"), local.code.languages.map((l) => ({ label: l.name, value: l.lines })), "lines");
    if (need("modules")) bars(need("modules"), local.code.modules.map((m) => ({ label: m.name, value: m.lines })), "lines");
  }
  if (releases) {
    // The API does not list releases newest first; publication time does.
    const stable = releases.filter((r) => r.tag_name.startsWith("v") && r.published_at)
      .sort((a, b) => b.published_at.localeCompare(a.published_at));
    setStat("releases", fmt.format(stable.length), stable.length);
    if (stable[0]) setStat("version", stable[0].tag_name);
    const downloads = stable.map((r) => ({ label: r.tag_name, value: r.assets.filter((a) => a.name.endsWith(".apk")).reduce((s, a) => s + a.download_count, 0) }));
    const total = downloads.reduce((s, d) => s + d.value, 0);
    setStat("downloads", fmt.format(total), total);
    if (need("downloads")) bars(need("downloads"), downloads, "APK downloads");
    if (need("latest") && stable[0]) latest(need("latest"), stable[0]);
    if (need("history")) history(need("history"), stable);
  }
  if (list instanceof Error) {
    ["heatmap", "weekly", "contributors", "contributors-row", "recent"].forEach((id) => need(id) && failed(need(id), list));
    return;
  }
  setStat("commits", fmt.format(list.length), list.length);
  const people = leaderboard(list, local ? local.aliases : {});
  const lead = people.find((p) => p.login === "ravibh5522");
  if (lead) {
    setStat("lead-commits", fmt.format(lead.commits));
    setStat("lead-share", Math.round((lead.commits / list.length) * 100) + "%");
  }
  if (need("heatmap")) heatmap(need("heatmap"), list);
  if (need("weekly")) columns(need("weekly"), weeklyRows(list), "commits");
  if (need("contributors-row")) peopleRow(need("contributors-row"), people);
  if (need("contributors")) contributorsTable(need("contributors"), people, list.length);
  if (need("recent")) recent(need("recent"), list, local ? local.aliases : {});
}

function latest(host, r) {
  const apk = r.assets.find((a) => a.name.endsWith(".apk"));
  const sha = r.assets.find((a) => a.name.endsWith(".sha256"));
  host.textContent = "";
  const info = host.appendChild(el("dl"));
  const add = (k, v) => { info.appendChild(el("dt", {}, k)); info.appendChild(el("dd", {}, v)); };
  add("Version", r.tag_name);
  add("Released", new Date(r.published_at).toLocaleDateString("en", { year: "numeric", month: "long", day: "numeric" }));
  if (apk) add("Size", (apk.size / 1048576).toFixed(1) + " MB");
  if (apk) add("Downloads", fmt.format(apk.download_count));
  const btns = host.appendChild(el("div", { class: "btns" }));
  btns.style.margin = 0;
  btns.appendChild(el("a", { class: "btn", href: apk ? apk.browser_download_url : r.html_url }, "Download APK"));
  if (sha) btns.appendChild(el("a", { class: "btn alt", href: sha.browser_download_url }, "SHA-256"));
  btns.appendChild(el("a", { class: "btn alt", href: r.html_url }, "Release notes"));
}

function history(host, list) {
  const table = host.appendChild(el("table"));
  const head = table.appendChild(el("tr"));
  ["Release", "Date", "APK downloads"].forEach((h, i) => head.appendChild(el("th", i === 2 ? { class: "num" } : {}, h)));
  list.forEach((r) => {
    const tr = table.appendChild(el("tr"));
    tr.appendChild(el("td")).appendChild(el("a", { href: r.html_url }, r.tag_name));
    tr.appendChild(el("td", {}, new Date(r.published_at).toLocaleDateString("en", { year: "numeric", month: "short", day: "numeric" })));
    tr.appendChild(el("td", { class: "num" }, fmt.format(r.assets.filter((a) => a.name.endsWith(".apk")).reduce((s, a) => s + a.download_count, 0))));
  });
}

const typing = document.getElementById("typer");
if (typing) typer(typing);
const heroClip = document.getElementById("hero-clip");
if (heroClip) clips(heroClip);
run();
